function attendanceHeatmap() {
  const months = [
    { name: 'May', days: 31, absent: [4, 9, 14, 19, 27], neutral: [11] },
    { name: 'Jun', days: 30, absent: [5, 10, 16, 22, 27], neutral: [17, 30] },
    { name: 'Jul', days: 31, absent: [3, 8, 13, 18, 24, 29], neutral: [15] },
    { name: 'Aug', days: 31, absent: [4, 9, 14, 19, 23, 27, 30], neutral: [12, 26] }
  ];
  let presentCount = 0;
  let absentCount = 0;
  let neutralCount = 0;
  const rows = months.map(month => {
    const absentDays = new Set(month.absent);
    const neutralDays = new Set(month.neutral);
    const cells = Array.from({ length: month.days }, (_, index) => {
      const day = index + 1;
      const status = neutralDays.has(day) ? 'no-class' : absentDays.has(day) ? 'absent' : 'present';
      const label = status === 'no-class' ? 'Holiday or no class scheduled' : status === 'absent' ? 'Absent' : 'Present';
      if (status === 'present') presentCount += 1;
      if (status === 'absent') absentCount += 1;
      if (status === 'no-class') neutralCount += 1;
      return `<span class="attendance-cell ${status}" role="img" aria-label="${month.name} ${day}: ${label}" title="${month.name} ${day}: ${label}"></span>`;
    }).join('');
    return `<div class="attendance-month-row"><span class="attendance-month-name">${month.name}</span><div class="attendance-grid monthly-attendance-grid" style="--days:${month.days}">${cells}</div></div>`;
  }).join('');
  const scheduledCount = presentCount + absentCount;
  const attendanceRate = Math.round((presentCount / scheduledCount) * 100);
  return `<section class="card attendance-heatmap-card" aria-labelledby="attendance-consistency-title">
    <div class="card-heading attendance-heatmap-heading"><div><h2 id="attendance-consistency-title">Attendance consistency</h2><p>Your daily attendance across the current and previous three demo months.</p></div><span class="pill green">4-month view</span></div>
    <div class="heatmap-summary"><div><strong>${presentCount}</strong><span>days present</span></div><div class="summary-divider"></div><div class="attendance-absence"><strong>${absentCount}</strong><span>days absent</span></div><div class="summary-divider"></div><div class="attendance-neutral"><strong>${neutralCount}</strong><span>holidays / no class</span></div><div class="attendance-streak"><span>Attendance rate</span><strong>${attendanceRate}%</strong></div></div>
    <div class="attendance-heatmap" aria-label="Attendance activity grid for May through August 2026 showing ${presentCount} present days, ${absentCount} absent days, and ${neutralCount} holidays or unscheduled days."><div class="heatmap-track"><div class="attendance-month-list">${rows}</div></div></div>
    <div class="attendance-legend"><span><i class="legend-cell present"></i>Present · ${presentCount} days</span><span><i class="legend-cell absent"></i>Absent · ${absentCount} days</span><span><i class="legend-cell no-class"></i>Holiday / no class · ${neutralCount} days</span><span class="legend-note">Each square represents one calendar day.</span></div>
  </section>`;
}

