function attendancePage() { return `<div class="page">${header('My Attendance', 'Your attendance helps you stay connected to learning.', false)}<section class="stat-grid">${stat('Attendance rate', '80%', '94 of 117 scheduled days', '#ddf5ee')}${stat('Days present', '94', 'May–August 2026', '#e8efff', 'gray')}${stat('Days absent', '23', 'Across four months', '#fff2d9', 'gray')}${stat('Holidays / no class', '6', 'Excluded from attendance rate', '#ddf5ee')}</section>${attendanceHeatmap()}<section class="content-grid"><article class="card"><div class="card-heading"><div><h2>Attendance journey</h2><p>You’re meeting your 80% target across the four-month period. Keep your steady rhythm going.</p></div></div>${chart('student')}</article><article class="card"><div class="card-heading"><div><h2>Subjects where you can improve</h2><p>Supportive next steps—not a judgment.</p></div></div><div class="signal-list"><div class="signal"><span class="signal-icon">∑</span><span class="signal-name">Mathematics<small>Target: 80%</small></span><b class="signal-val">74%</b></div><div class="signal"><span class="signal-icon" style="--tint:#fff3e0;--colour:#b76c00">⌘</span><span class="signal-name">Programming<small>Target: 80%</small></span><b class="signal-val">74%</b></div><div class="signal"><span class="signal-icon" style="--tint:#e4f5ef;--colour:#187564">ϟ</span><span class="signal-name">Physics<small>On target</small></span><b style="color:#187564">89%</b></div></div></article></section></div>`; }
