function studentInterventions() { return `<div class="page">${header('My Support Plan', 'Additional support is here to help you move forward.', false)}<section class="content-grid"><article class="card"><div class="card-heading"><div><h2>You have a new support plan</h2><p>Assigned by Prof. Kiran Rao · Reviewed together</p></div><span class="pill blue">Active</span></div><div class="insight-callout"><strong>Academic mentoring</strong><p>We noticed a few areas where extra support may help. This plan focuses on Mathematics practice and a regular mentor check-in.</p></div><div class="plan-item" style="margin-top:10px"><span class="plan-check">✓</span><span><strong>Meet your mentor</strong><span>Friday, 3:30 PM</span></span><span class="plan-duration">Upcoming</span></div><div class="plan-item"><span class="plan-check todo">○</span><span><strong>Complete practice set</strong><span>Ten Mathematics questions</span></span><span class="plan-duration">This week</span></div><div class="plan-item"><span class="plan-check todo">○</span><span><strong>Attend revision session</strong><span>Tuesday · Room B-204</span></span><span class="plan-duration">Tue</span></div></article><article class="card"><div class="card-heading"><div><h2>Progress after support</h2><p>Demo / simulated progress</p></div></div><div class="change"><strong>Mathematics</strong><span>52% → 68%</span><small style="color:#187564">↑ 16 percentage points</small></div><div class="insight-callout" style="margin-top:13px"><strong>Great progress—keep your routine.</strong><p>Continue using your weekly plan and bring any difficult topics to your mentor.</p></div></article></section></div>`; }
function studentFeedback() { return `<div class="page">${header('Student Feedback', 'Help improve the learning environment for everyone.', false)}<section class="content-grid"><article class="card feedback-form"><div class="card-heading"><div><h2>Share your experience</h2><p>Your feedback helps the college understand recurring issues. You can submit anonymously.</p></div></div><div class="field"><span>What would you like to share?</span><div class="category-buttons">${['Internet / Wi-Fi', 'Classroom', 'Library', 'Teaching support', 'Canteen', 'Campus environment'].map(c => `<button type="button" class="category-button ${state.selectedCategory === c ? 'active' : ''}" data-category="${c}">${c}</button>`).join('')}</div></div><div class="field"><span>How would you rate it?</span><div class="rating" role="group" aria-label="Choose a rating from 1 to 5">${[1, 2, 3, 4, 5].map(n => `<button type="button" class="${n <= state.rating ? 'selected' : ''}" data-rating="${n}" aria-label="${n} stars">★</button>`).join('')}</div></div><label class="field">Your feedback<textarea id="feedback-text" placeholder="Tell us what is working or what could be improved..."></textarea></label><label class="check-row"><input id="anonymous" type="checkbox" checked /> Submit anonymously</label><button class="primary wide" data-action="submit-feedback">Submit feedback</button></article><article class="card"><div class="card-heading"><div><h2>Your privacy matters</h2><p>How SAGE handles feedback</p></div></div><div class="signal-list"><div class="signal"><span class="signal-icon">◌</span><span class="signal-name">Anonymous by choice<small>Staff insights are aggregated by default.</small></span></div><div class="signal"><span class="signal-icon" style="--tint:#e4f5ef;--colour:#187564">✓</span><span class="signal-name">Action-focused<small>Feedback is grouped into recurring themes.</small></span></div><div class="signal"><span class="signal-icon" style="--tint:#eaf2ff;--colour:#3e69d6">⌁</span><span class="signal-name">No automatic judgments<small>Feedback is never used for disciplinary decisions.</small></span></div></div><div class="explanation" style="margin-top:16px">Your feedback joins an aggregate view that helps staff identify potential institutional support barriers.</div></article></section></div>`; }
function notificationsPage() { return `<div class="page">${header('Notifications', 'Helpful reminders and positive updates.', false)}<section class="card"><div class="plan-item"><span class="plan-check">✦</span><span><strong>You earned the 7-Day Learner badge!</strong><span>Keep building a study habit that works for you.</span></span><span class="plan-duration">Today</span></div><div class="plan-item"><span class="plan-check">◷</span><span><strong>Mathematics study goal is due today</strong><span>A 45-minute focus session is ready when you are.</span></span><span class="plan-duration">Today</span></div><div class="plan-item"><span class="plan-check">◌</span><span><strong>Your mentor scheduled a check-in</strong><span>Friday at 3:30 PM · Academic mentoring</span></span><span class="plan-duration">Yesterday</span></div></section></div>`; }
function profilePage() { return `<div class="page">${header('My Profile', 'The information you choose to share with your learning support team.', false)}<section class="content-grid"><article class="card profile-card"><span class="avatar mint" style="width:68px;height:68px;font-size:20px">AS</span><span><h2>Aarav Sharma</h2><p>STU-2026-0147 · B.Tech Computer Science · Semester 3</p><p style="margin-top:7px">Level 3 · 1,240 XP · 7-day streak</p></span></article><article class="card"><div class="card-heading"><div><h2>Study preferences</h2><p>Used to make your plan more useful.</p></div></div><p style="color:#536278;font-size:12px;line-height:1.7">Preferred focus time: 6:00–7:30 PM<br>Goal style: Short daily sessions<br>Reminder preference: Evening notification</p><button class="secondary" data-action="note">Update preferences</button></article></section></div>`; }

function genericPage() { const title = pageName(); return `<div class="page">${header(title, 'A prototype view within the SAGE student-support platform.')}<section class="card"><div class="card-heading"><div><h2>${title}</h2><p>This view is ready to be connected to your real institutional data and workflow.</p></div></div><div class="insight-callout"><strong>Prototype-ready foundation</strong><p>SAGE uses synthetic data in this demo. Any real deployment must include local validation, role-based access, human review, and appropriate privacy safeguards.</p></div></section></div>`; }

function renderPage() {
  const content = document.querySelector('#page-content');
  if (!content) return;
  let template;
  if (state.role === 'admin') template = state.page === 'dashboard' ? adminDashboard() : state.page === 'feedback' ? feedbackDashboard() : state.page === 'students' ? profileDetail() : genericPage();
  else if (state.role === 'faculty') template = state.page === 'dashboard' ? facultyDashboard() : state.page === 'students' ? profileDetail() : genericPage();
  else {
    const pages = { dashboard: studentDashboard, attendance: attendancePage, performance: performancePage, helper: helperPage, plan: planPage, goals: goalsPage, achievements: achievementsPage, interventions: studentInterventions, feedback: studentFeedback, notifications: notificationsPage, profile: profilePage };
    template = (pages[state.page] || genericPage)();
  }
  content.innerHTML = template;
  document.querySelector('.sidebar')?.classList.remove('open');
  content.querySelectorAll('[data-page]').forEach(btn => btn.addEventListener('click', () => { state.page = btn.dataset.page; renderPage(); }));
  content.querySelectorAll('[data-action]').forEach(btn => btn.addEventListener('click', actionHandler));
  content.querySelectorAll('[data-category]').forEach(btn => btn.addEventListener('click', () => { state.selectedCategory = btn.dataset.category; renderPage(); }));
  content.querySelectorAll('[data-rating]').forEach(btn => btn.addEventListener('click', () => { state.rating = Number(btn.dataset.rating); renderPage(); }));
  content.querySelector('#chat-form')?.addEventListener('submit', sendChat);
}

function actionHandler(event) {
  const action = event.currentTarget.dataset.action;
  if (action === 'theme') { toggleTheme(); return; }
  if (action === 'logout') { clearInterval(state.timer); state.page = 'dashboard'; showWelcome(); return; }
  if (action === 'student-detail') { state.page = 'students'; if (state.role === 'admin') state.page = 'students'; renderPage(); return; }
  if (action === 'intervention') { showModal('Review support plan', `<p>Assigning a plan always needs human approval. In this demo, the plan contains mentoring, guided practice, and a follow-up check-in.</p><label class="field">Faculty note<textarea placeholder="Add a supportive note for the student"></textarea></label><button class="primary wide" id="confirm-intervention">Assign support plan</button>`); document.querySelector('#confirm-intervention').addEventListener('click', () => { closeModal(); toast('Support plan assigned. Aarav will see a supportive next-step view.'); }); return; }
  if (action === 'issue-modal') { showModal('Wi-Fi connectivity', `<p><b>43 simulated feedback mentions</b> · Average rating: <b>2.1 / 5</b> · Trend: <b>Increasing</b></p><div class="explanation" style="margin-top:15px">“Wi-Fi doesn’t reach the second floor.”<br><br>“Library connection keeps dropping.”<br><br>“Internet is too slow during study time.”</div><label class="field">Update issue status<select id="issue-status"><option>Under review</option><option>Action planned</option><option>In progress</option><option>Resolved</option></select></label><label class="field">Staff note<textarea placeholder="e.g. IT department notified. Access point planned."></textarea></label><button class="primary wide" id="save-issue">Save update</button>`); document.querySelector('#save-issue').addEventListener('click', () => { closeModal(); toast('Issue action updated. Student feedback remains protected in aggregate reporting.'); }); return; }
  if (action === 'submit-feedback') { const feedback = document.querySelector('#feedback-text')?.value.trim(); if (!state.rating) { toast('Choose a star rating before submitting.'); return; } if (!feedback) { toast('Add a short comment so staff can understand the issue.'); return; } showModal('Feedback submitted', `<p>Thank you for helping improve the student experience. Your feedback is now part of the aggregated <b>${state.selectedCategory}</b> insight.</p><div class="insight-callout" style="margin-top:15px"><strong>${document.querySelector('#anonymous')?.checked ? 'Submitted anonymously' : 'Submitted with your identity'}</strong><p>Staff normally view aggregate feedback patterns. No automatic action is taken from a single submission.</p></div><button class="primary wide" id="done-feedback">Done</button>`); document.querySelector('#done-feedback').addEventListener('click', () => { closeModal(); state.rating = 0; toast('Your feedback was recorded. Thank you.'); renderPage(); }); return; }
  if (action === 'focus') { showFocusModal(); return; }
  if (action === 'help') { showModal('Need support?', `<p>SAGE can help you reach the right person. This demo does not provide emergency services or mental-health diagnosis.</p><div class="plan-item"><span class="plan-check">◌</span><span><strong>Talk to a mentor</strong><span>Academic planning and study support</span></span></div><div class="plan-item"><span class="plan-check">◌</span><span><strong>Request academic help</strong><span>Subject-specific support</span></span></div><div class="plan-item"><span class="plan-check">◌</span><span><strong>Request counselor support</strong><span>Connect with your college support service</span></span></div><button class="primary wide" id="help-request">Send support request</button>`); document.querySelector('#help-request').addEventListener('click', () => { closeModal(); toast('Support request prepared for the appropriate team.'); }); return; }
  if (action === 'notifications') { state.role === 'student' ? (state.page = 'notifications', renderPage()) : toast('No new notifications.'); return; }
  if (action === 'note') { toast('This prototype action is ready for your backend integration.'); }
}

function showModal(title, body) { document.body.insertAdjacentHTML('beforeend', `<div class="modal-backdrop" id="modal-backdrop" role="dialog" aria-modal="true" aria-label="${title}"><section class="modal"><div class="modal-top"><div><h2>${title}</h2><p>Demo prototype</p></div><button class="icon-button" id="modal-close" aria-label="Close">×</button></div>${body}</section></div>`); document.querySelector('#modal-close').addEventListener('click', closeModal); document.querySelector('#modal-backdrop').addEventListener('click', e => { if (e.target.id === 'modal-backdrop') closeModal(); }); }
function closeModal() { clearInterval(state.timer); state.timer = null; document.querySelector('#modal-backdrop')?.remove(); }
function showFocusModal() { state.seconds = 25 * 60; showModal('Focus session', `<p>Choose one task, remove distractions, and give it your full attention.</p><div style="text-align:center;padding:20px 0"><div id="timer" style="font:800 54px 'Plus Jakarta Sans';letter-spacing:-.08em;color:#146c62">25:00</div><div style="color:#718096;font-size:12px;margin-top:7px">Mathematics · Algebra revision</div></div><button class="primary wide" id="timer-start">Start focus timer</button><button class="secondary wide" style="margin-top:9px" id="timer-complete">Complete session</button>`); document.querySelector('#timer-start').addEventListener('click', startTimer); document.querySelector('#timer-complete').addEventListener('click', () => { closeModal(); toast('Session completed! You earned +20 XP for focused learning.'); }); }
function startTimer() { const button = document.querySelector('#timer-start'); if (state.timer) { clearInterval(state.timer); state.timer = null; button.textContent = 'Resume focus timer'; return; } button.textContent = 'Pause timer'; state.timer = setInterval(() => { state.seconds--; const mins = Math.floor(state.seconds / 60); const secs = state.seconds % 60; const timer = document.querySelector('#timer'); if (timer) timer.textContent = `${String(mins).padStart(2, '0')}:${String(secs).padStart(2, '0')}`; if (state.seconds <= 0) { clearInterval(state.timer); state.timer = null; closeModal(); toast('Session completed! You earned +20 XP.'); } }, 1000); }
function sendChat(e) { e.preventDefault(); const input = e.currentTarget.querySelector('input'); const text = input.value.trim(); if (!text) return; const messages = document.querySelector('#chat-messages'); messages.insertAdjacentHTML('beforeend', `<div class="chat-message you"><strong>You</strong>${escapeHtml(text)}</div>`); input.value = ''; setTimeout(() => { messages.insertAdjacentHTML('beforeend', `<div class="chat-message"><strong>SAGE study helper</strong>Based on the available progress data, keep your next step small and specific: revise one Mathematics concept, try a few questions, and note what you want to clarify with your teacher. You’re building momentum.</div>`); messages.scrollTop = messages.scrollHeight; }, 350); }
function escapeHtml(value) { return value.replace(/[&<>'"]/g, char => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', "'": '&#39;', '"': '&quot;' }[char])); }
function toast(message) { const region = document.querySelector('#toast-region'); const id = `toast-${Date.now()}`; region.insertAdjacentHTML('beforeend', `<div class="toast" id="${id}"><strong>✓</strong>${message}</div>`); setTimeout(() => document.querySelector(`#${id}`)?.remove(), 4200); }
function applyTheme() { document.documentElement.dataset.theme = state.theme; }
function toggleTheme() {
  state.theme = state.theme === 'light' ? 'dark' : 'light';
  try { localStorage.setItem('sage-theme', state.theme); } catch { /* Theme remains available for this session. */ }
  applyTheme();
  if (document.querySelector('.shell')) shell(); else showWelcome();
}

applyTheme();
showWelcome();
